<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class FiscalCatalogVersion extends Model {use HasUuids;protected $fillable=['name','version','status','valid_from','valid_to','source_filename','source_sha256','storage_path','manifest','created_by','approved_by','approved_at','published_at'];protected function casts():array{return ['manifest'=>'array','valid_from'=>'date','valid_to'=>'date','approved_at'=>'datetime','published_at'=>'datetime'];}public function ncmEntries(){return $this->hasMany(NcmClassTribEntry::class,'catalog_version_id');}public function cstEntries(){return $this->hasMany(CstCatalogEntry::class,'catalog_version_id');}public function cclassEntries(){return $this->hasMany(CclassCatalogEntry::class,'catalog_version_id');}public function issues(){return $this->hasMany(CatalogImportIssue::class,'catalog_version_id');}public function scopePublished($q){return $q->where('status','published');}}
